#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn packs_lsb_first() {
        let mut r = Regs::new();
        r.set(sw02::IN_ENDIAN, 1)
            .set(sw02::STREAM_LASTPACKET, 1)
            .set(sw02::DEC_MODE, 3);
        assert_eq!(r.get(sw02::IN_ENDIAN), 1);
        assert_eq!(r.get(sw02::DEC_MODE), 3);
        assert_eq!(r.w[sw02::WORD] & 0x3, 0b01);
    }

    #[test]
    fn array_words_are_distinct() {
        assert_eq!(sw10_24::word(0), 10);
        assert_eq!(sw10_24::word(14), 24);
        assert_eq!(sw25_39::word(0), 25);
        assert_eq!(sw49_63::word(14), 63);
    }
}
